'use strict';

// Validate the rendered Compose configuration, not just text in YAML.
// The input is generated by docker compose config (all profiles included).
const assert = require('node:assert/strict');
const fs = require('node:fs');

const file = process.argv[2];
if (!file) throw Error('Pass the rendered Docker Compose JSON path');
const services = JSON.parse(fs.readFileSync(file, 'utf8')).services;
function assertLocal(name) {
  const service = services[name];
  assert(service, 'Missing expected service: ' + name);
  for (const port of service.ports || []) {
    const hostIp = port.host_ip || port.hostIp || '';
    assert.equal(hostIp, '127.0.0.1',
      name + ' must not publish a service port outside the local host');
  }
}
for (const service of ['fuseki', 'redis', 'mailcatcher', 'arena', 'tripleadmin']) {
  assertLocal(service);
}
const secret = services.fuseki.environment.ADMIN_PASSWORD;
assert(secret && secret === process.env.SEMAPPS_JENA_PASSWORD &&
       secret !== 'admin' && Buffer.byteLength(secret, 'utf8') >= 24,
  'Fuseki admin password must be supplied and sufficiently strong');
assert((services.arena.profiles || []).includes('admin'));
assert((services.tripleadmin.profiles || []).includes('admin'));
assert.equal(services.tripleadmin.environment.TRIPLEADMIN_HOST,
  'http://fuseki:3030/');
console.log(JSON.stringify({
  success: true,
  policy: 'private-compose-service-ports-and-explicit-fuseki-secret',
  checkedServiceCount: 5,
  adminDashboardsDisabledByDefault: true
}));
